mapper.select:
SELECT cc.course_id AS courseId, c.course_name AS courseName, c.course_image_url AS coverUrl, c.course_introduction AS description, c.teacher_Id AS teacherId, teacher.nickname AS teacherName, c.indicator_id AS indicatorId, indicator.indicator_name AS indicatorName FROM ( SELECT binding.course_id, binding.claim_teacher_id, ROW_NUMBER() OVER (PARTITION BY binding.course_id ORDER BY CASE WHEN binding.claim_teacher_id IS NULL THEN 1 ELSE 0 END, CASE WHEN TRIM(binding.semester_name) = TRIM((SELECT cfg.`value` FROM infra_config cfg WHERE cfg.config_key = 'edu.current.semester.name' AND cfg.deleted = 0 ORDER BY cfg.id DESC LIMIT 1)) THEN 0 ELSE 1 END, binding.id DESC) AS teacher_rank FROM edu_class_course binding JOIN edu_class ec ON binding.class_id = ec.id AND ec.deleted = 0 AND ec.status = 0 WHERE binding.class_id IN
#{classId}
AND binding.deleted = 0 AND binding.status = 0 ) cc JOIN capacity_course c ON cc.course_id = c.id AND c.deleted = 0 AND c.status = 0 LEFT JOIN system_users teacher ON teacher.id = CASE WHEN c.is_public_course = 0 THEN COALESCE(cc.claim_teacher_id, c.teacher_Id) ELSE c.teacher_Id END AND teacher.deleted = 0 LEFT JOIN capacity_indicator indicator ON indicator.id = c.indicator_id AND indicator.deleted = 0 WHERE cc.teacher_rank = 1
